export function normalizeTaskTitle(value) {
  if (typeof value !== 'string') throw new TypeError('title must be text');
  const title = value.trim();
  if (!title) throw new RangeError('title is required');
  return title;
}

async function saveTask(repository, task) {
  const saved = await repository.insert(task); // await actual persistence
  if (!saved?.id) throw new Error('Save failed');
  return saved;
}
